INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(352300, 0, 3523, 0, 0, 0, 'Netherstorm', 'Netherstorm was once the Plains of Farahlon, green country that a Kirin Tor mage could compare to Westfall only months ago. When Ner''zhul''s portals tore Draenor apart it was left a scatter of floating islands at the edge of the Twisting Nether, and now Prince Kael''thas is finishing the ruin. From Tempest Keep, the fortress his blood elves hold, he has raised great manaforges that pull energy out of the sky and pipe it away underground, and their strain is tearing the land apart; one goblin scientist gives the region only months. Many have come to exploit or oppose him. The ethereal traders of the Consortium rule from the Stormspire, the Protectorate hunts a void lord and the renegade Ethereum, the goblins of Area 52 build a rocket to fly into the Nether, and the ghosts of a Kirin Tor village mourn their dead. In the north the Burning Legion builds fel reavers under the eredar Socrethar, while envoys of the Aldor and the Scryers quarrel at the Area 52 inn.', 'warcraft.wiki.gg/wiki/Netherstorm (Farahlon, Ner''zhul''s portals, edge of the Twisting Nether, Kael''thas and Tempest Keep, manaforges, Consortium, Protectorate, Area 52, Legion forge bases, Socrethar); npc_text 9826 (Ravandwyr: once the Plains of Farahlon); npc_text 9901 (Vargoth image: mere months ago the fields would not have looked out of place in Westfall); quest 10189 description (manaforges sucking energy from the sky); quest 10193 description (warp-energy delivered via underground pipes); quest 10183 reward text (nether energies will rip everything to shreds in a few months); npc_text 10022 (innkeeper: arrivals from Shattrath arguing); quests 10339, 10437, 10855 descriptions'),
(352301, 1, 3523, 1, 0, 0, 'Area 52', 'Area 52 is a walled goblin town on the southwestern island of Netherstorm and the headquarters of B.O.O.M., the Braintrust of Orbital Operations and Mechanics. Its pride is the half-built X-52 Nether-Rocket, overseen by Rocket-Chief Fuselage. Bruisers and towering death machines keep the peace, and sappers work a fissure the goblins blasted through the middle of town, where a few workers glow suspiciously and the lead sapper insists radiation is nothing to worry about. The town is neutral ground. A Kirin Tor apprentice waits here for help, a Consortium agent hunts traitors, and envoys of the Aldor and the Scryers, newly arrived from Shattrath, argue so constantly that the innkeeper worried they would drive off trade.', 'warcraft.wiki.gg/wiki/Area_52 (neutral goblin town, southwestern island, B.O.O.M., X-52, bruisers and death machines, Irradiated Worker and Manager); npc_text 9844 (Fuselage: Braintrust of Orbital Operations and Mechanics); quest 10203 description (fissure running through Area 52, we did that); npc_text 9869 (Blastfizzle: radiation, no need to worry); npc_text 10022 (Innkeeper Remi Dodoso); zone_areas 3712: Ravandwyr 19217, Khay''ji 19880, Orelis, Karja, Thalodien, Larynna, Area 52 Bruiser, Death Machine, Irradiated Worker 19610'),
(352302, 1, 3523, 2, 0, 0, 'Ruins of Enkaat', 'North of Area 52 lie the Ruins of Enkaat, an old draenei settlement fallen to rubble. Its dead have not left. Disembodied vindicators, protectors and even exarchs drift among the broken walls and attack anyone who comes near, and the goblins have taken a keen interest in the crystals they carry. The goblins of Area 52 gather etherlithium crystals here for their rocket''s engine matrix, a goblin bot specialist salvages fragile draenei machines with the help of a robot called the Maxx A. Million, and the Kirin Tor apprentice Ravandwyr has heard that a crystal carried by these ghosts could mend his master''s broken staff.', 'quest 10186 description (crystals at the Ruins of Enkaat, never mind the draenei ghosts); quests 10190, 10191 (Bot-Specialist Alley, Maxx A. Million Mk. V, fragile draenei machines, ghosts); quest 10300 description (crystals carried by the ghosts at the Enkaat Ruins); zone_areas 3725: Disembodied Vindicator 18872, Protector 18873, Exarch 21058, Etherlithium Matrix Crystal x25, Alley 19578; warcraft.wiki.gg/wiki/Netherstorm (Ruins of Enkaat northwest of Area 52, restless draenei spirits)'),
(352303, 1, 3523, 3, 0, 0, 'Arklon Ruins', 'Southeast of Area 52 stand the Arklon Ruins, another old draenei settlement. When Archmage Vargoth''s apprentice Ravandwyr fled the attack on the Violet Tower, he sought refuge here and walked straight into the leading edge of a Burning Legion force, which wrested his master''s staff from him; it ended in the hands of their leader, Ekkorash. The demons have stayed. Doomguard keep watch while artifact seekers dig for something under the dreadlord Pentatharon, and the goblin sapping crew that worked here left its machinery behind when the Legion moved in. Beyond the ruins, Farahlon giants walk the heights of Arklonis Ridge.', 'npc_text 9828 (Ravandwyr: refuge in the old draenei settlement of Arklon, Legion force, staff wrested from him); quest 10173 description (Arklon Ruins southeast, Ekkorash has the staff); creature 19493 Ekkorash the Inquisitor; quest 10265 description and reward (Pentatharon, Legion excavating, searching for something); quest 10203 description (B.O.O.M. operation at the Arklon Ruins until the Legion moved in); zone_areas 3723: Artifact Seeker 19852, Felblade Doomguard 19853, Pentatharon 20215, goblin equipment objects; 3921: Farahlon Giant x6'),
(352304, 1, 3523, 4, 0, 0, 'The Crumbling Waste', 'The Crumbling Waste is the broken rim of the island south of Area 52, a long ledge where the land gives way to open sky. Phase hunters drift in from the nether along its edges, nether rays and mana snappers roam the slopes, and sundered rumblers and warp aberrations haunt the southern shelf. The goblins see resources everywhere. Chief Engineer Trep sends crews to wring solid power out of the rumblers and aberrations for the X-52''s engines, and Rocket-Chief Fuselage has posted a wanted notice for Netherock, king of the local mountain giants, who has been interfering with operations all along the south ledge.', 'quest 10190 description (phase hunters floating in from the nether at the island''s edges); quest 10226 description (sundered rumblers and warp aberrations on the ledge of the Crumbling Wastes to the south); quest 10701 description (Netherock, king of the local mountain giants, south ledge of the island); zone_areas 3721: Phase Hunter, Nether Beast, Mana Snapper, Sundered Rumbler, Nether Ray, Warp Aberration, Netherock 20772'),
(352305, 1, 3523, 5, 0, 0, 'Manaforge B''naar', 'Manaforge B''naar, west of Area 52, was the first of Kael''thas''s great purple engines that the envoys from Shattrath set out to study. Its warp-masters and warp-engineers oversee the gathering of what they call warp-energy and its delivery through underground pipes to a distant destination, while geologists survey the ground and magisters and bloodwarders stand guard, with a ballista team posted outside. The magisters charge small bloodgem shards from great crystals and drink deep of the result. Readings taken where the pipelines plunge into the earth show warp energies strong enough to shatter what remains of Outland, and its console turns out to be naaru work.', 'quest 10189 description (manaforge, large purple buildings, Captain Arathyn''s ballista team); quest 10193 description (warp-masters, warp-engineers, geologists, underground pipes); quest 10204 description and reward (bloodgem crystals, magnified addiction); quest 10313 description and reward (pipeline ends, energies could shatter Outland); quests 10243, 10245, 10299 (console code like naaru technology); quest 10261 description (B''naar to the west of Area 52); zone_areas 3726: Sunfury Bloodwarder, Geologist, Warp-Engineer, Magister, Warp-Master, Overseer Theredis 20416'),
(352306, 1, 3523, 6, 0, 0, 'The Heap', 'South of Area 52 lies the Heap, a junkyard of salvage that the goblins of B.O.O.M. consider their claim. The Zaxxis ethereals disagree. Once part of the Consortium, the Zaxxis broke away to go into business for themselves and have even cut deals with the Sunfury blood elves, so the Consortium''s Nether-Stalker Khay''ji wants their insignia and Warp-Raider Nesaad dead, who somehow survived Khay''ji''s attack on him. The goblins simply raid the ethereals'' camp for its technology. Nearby sits a scrapped fel reaver, and the goblin salvager N. D. Meancamp, crouched where the Zaxxis cannot see him, is determined to have its heart.', 'quest 10206 description (The Heap to the south is ours, ethereals stealing); quest 10262 description (Zaxxis cut relationship with the Consortium, deals with the Sunfury); quest 10205 description (Nesaad survived my attack, camp in the southwestern corner of the Heap); quest 10309 description (scrapped fel reaver, Zaxxis ethereals); npc_text 9904 (Meancamp: keep it down, this is MY claim); zone_areas 3729: Zaxxis Raider, Zaxxis Stalker, Warp-Raider Nesaad 19641, Scrapped Fel Reaver 20243, Meancamp 19690'),
(352307, 1, 3523, 7, 0, 0, 'Eco-Dome Midrealm', 'Across the bridge east of Area 52, the Consortium has raised Eco-Dome Midrealm, a bubble of living green on the ruined plains. Inside, lynxes, moths and crocolisks thrive among plants that grow faster than they should, including the ivory bell, a healing herb the ethereals sell at a steep price to the Cenarion Expedition. At the Midrealm Post the trader Gahruj handles the Consortium''s quarrels with the blood elves and the technician Mehrdad worries over a failing dome generator, while two goblins watch the ethereals closely: Mama Wheeler of Area 52, eager to learn their secrets, and a fellow who claims to be a simple furrier.', 'quest 10266 description (east of Area 52 across the bridge, Midrealm Post just inside Eco-Dome Midrealm); quest 10348 description and reward (ivory bell for the Cenarion Expedition, a lot of money); quest 10418 reward (domes accelerate growth); quest 10417 description (generator damage); npc_text 9947 (Gahruj on the blood elves); npc_text 9919 (Mama Wheeler: learn a lot, maybe get some for myself); quest 10433 description (Shauly posing as a simple furrier); zone_areas 3877/3851: Ripfang Lynx, Shimmerwing Moth, Barbscale Crocolisk, Ivory Bell; Gahruj, Mehrdad, Mama Wheeler, Shauly Pore'),
(352308, 1, 3523, 8, 0, 0, 'The Scrap Field', 'East of Eco-Dome Midrealm, the Burning Legion has seized a goblin salvage claim, the Scrap Field. Huge fel reaver parts litter the ground, gan''arg engineers and mo''arg doomsmiths labor among them, and their overseer Doomclaw keeps to the eastern end beneath the great pipe, driving his workers and promising to come for the little goblins. The demons never run short of hands. South of the field, at a camp they call Invasion Point: Destroyer, a warp-gate brings in a steady flow of reinforcements, and the Consortium''s Drijya has slipped down there to sabotage it, pylon by pylon.', 'quest 10232 description (Legion moved in on our claim at the Scrap Field); quest 10234 description (to the east of Midrealm Post, huge fel reaver parts); quest 10235 description (Doomclaw in the eastern part under the pipe); creature_text 19738 (Doomclaw); quest 10311 description (reinforcements from Invasion Point: Destroyer to the south); quest 10310 and creature_text 20281 (pylons, heat manifold); zone_areas 3727: Gan''arg Engineer, Mo''arg Doomsmith, Doomclaw 19738, Fel Reaver Part; 3882: Warp-Gate Engineer'),
(352309, 1, 3523, 9, 0, 0, 'Manaforge Coruu', 'Manaforge Coruu stands east of Area 52 near Kirin''Var, and its arcanist boasts of having more than doubled the energy it sends to Tempest Keep. A regiment of Sunfury arcanists and researchers works here under Arcanist Ardonis, and Spellbinder Maryana keeps the Sigil of Krasus, taken from Archmage Vargoth. The forge is watched. Scryer spies hide outside it, and under an illusion one of their agents overheard Commander Dawnforge order Ardonis to reinforce Manaforge Duro. The argument ended when an image of Pathaleon the Calculator appeared, insisting that Duro would be reinforced and that Prince Kael''thas would tolerate no further delays.', 'npc_text 9926 (Ardonis: more than doubled the energy sent to Tempest Keep, another Ultris); quests 10194, 10321 (Coruu to the east); quest 10246 description (regiment of arcanists and researchers); quest 10188 description (Kael''thas gave the sigil to Spellbinder Maryana); quests 10652, 10197, 10198 (spies, illusion, Dawnforge meeting Ardonis); creature_text 19831, 19830, 21504 groups 0-3 (Pathaleon the Calculator''s Image); zone_areas 3730: Ardonis 19830, Dawnforge 19831, Maryana 19593, Caledis 19840, Lariel 19839, Seylanna 20397; src/server/scripts/Outland/zone_netherstorm.cpp (Dawnforge, Ardonis and Pathaleon image event at Coruu)'),
(352310, 1, 3523, 10, 0, 0, 'Kirin''Var Village', 'Kirin''Var Village was built by the Kirin Tor mages of the Alliance expedition once they knew they were trapped in Outland, and by the custodian''s count it held for twenty years against countless orc assaults. It did not survive Prince Kael''thas. His forces leveled the town, and the mana bomb that opened the attack tore a rift through which mana creatures still stream into the ruins of Wizard Row. Now the dead keep the village. Ghostly apprentices haunt the Town Square, a maddened spectral smith lingers in his old workshop, tormented souls wander the Chapel Yard, and an old farmer pines for his lost cow. By the lieutenant-sorcerer''s account, only two spirits remember who they were.', 'quest_template 10179 description (Vargoth: expedition trapped, Kirin Tor contingent built Kirin''Var on the Plains of Farahlon); npc_text 9848 (Dieworth: 20 long years and countless orc assaults); quest 10343 description and reward (thundering noise and flash, mana bomb, rift in the nether, mana creatures); quest 10185 description (mana elementals drawn to the ruins of Wizard Row); npc_text 9847 (Morran: only the custodian and I retain our identities); quests 10331, 10332 (Master Rhonsus attacked); quest 10334 (Thadell searched the fields and Chapel Yard for Bessy); zone_areas 3934, 3935, 3879: Severed Spirit, Kirin''Var Apprentice, Rhonsus 20410, Mana Seeker, Mageslayer, Mana Bomb Fragment, Tormented Soul, Tormented Citizen; warcraft.wiki.gg/wiki/Kirin''Var_Village (mana bomb dropped on Wizard Row)'),
(352311, 1, 3523, 11, 0, 0, 'The Violet Tower', 'At the heart of Kirin''Var rises the Violet Tower, sanctuary and prison to Archmage Vargoth. When Kael''thas took the village he stripped the archmage of his possessions and sealed the tower with a curse that no member of the Kirin Tor may cross in either direction, so that Vargoth''s own people cannot reach him. A traitor made it possible: the apprentice Naberius, drawn to necromancy, handed the secrets of the tower''s defenses to the blood elves. An arcane golem named Ar''kelos guards the base and smothers the archmage''s magic, and the key to the curse lies far away in Tempest Keep, held by one of the prince''s commanders.', 'quest 10174 description (sanctuary and prison, Kirin Tor can neither enter nor leave); npc_text 9848 (ward forbids passage of any of the Kirin Tor); quest 10188 description (Kael''thas divested me of my possessions); quest 10319 description (Naberius handed over the secrets to the tower''s defense); quest 10176 description and reward (Ar''kelos at the bottom of the tower, dampening field); quests 10256, 10257 (Commander Sarannis holds the keystone in Tempest Keep); quest 10176 log text (Violet Tower at the center of Kirin''Var Village)'),
(352312, 1, 3523, 12, 0, 0, 'Sunfury Hold', 'North of the Violet Tower lies Sunfury Hold, the camp to which Kael''thas''s forces withdrew after destroying Kirin''Var. The village''s ghostly custodian says the very soldiers who killed them toast their amazing victory here, among the tents and ballistae, the archers and flamekeepers. Its commander, Spellreaver Marathelle, carried off the heliotrope oculus that unlocks Krasus''s Compendium during the attack, no doubt taking it for a pretty bauble. Custodian Dieworth wants the garrison slain, and Lieutenant-Sorcerer Morran wants every tent and siege engine burned to ash, so that Kael''s zealous followers have nothing to return to.', 'quest 10222 description (withdrew to Sunfury Hold to the northeast, toast their amazing victory); quest 10301 description and reward (Spellreaver Marathelle looted the oculus, Sunfury Hold northeast of the tower, local commander); quest 10233 description (Morran: tents and artillery must burn, zealous and tenacious); creature_text 19926; zone_areas 3837: Sunfury Archer, Sunfury Flamekeeper, Invis BE Ballista, Invis BE Tent, Marathelle 19926'),
(352313, 1, 3523, 13, 0, 0, 'Manaforge Duro', 'Manaforge Duro, east of Eco-Dome Midrealm, is the forge slipping out of its masters'' hands. Its rising output has drawn swarms of errant mana creatures, the Sunfury garrison is losing control, and the Aldor fear that an explosion here could set off a chain reaction across Outland. Its defenders include notorious names. Master Daellis Dawnstrike, the crimson-armored archer who led the attack on Kirin''Var, has been sent here to restore order, and Summoner Kanthin keeps Archmage Vargoth''s familiar, Glacius, as a trophy. The blood elves also hold a shipment of Consortium surveying equipment they never paid for, and west of the forge roams Apex, a giant that bears great crystals.', 'quest 10322 description (Sunfury losing control, mana creatures, chain reaction); quest 10267 description (Duro to the east of Midrealm Post, unpaid surveying equipment, mana creatures); quest 10223 description (crimson armor, ordered to Manaforge Duro, his bow); quest 10209 description (Kanthin holds Glacius as a trophy, stationed at Duro); quest 10256 description (crystal-bearing giant Apex roams the plains west of Manaforge Duro); zone_areas 3734: Daellis 19705, Kanthin 19657, Glacius 19653, Overseer Athanel 20435, Box of Surveying Equipment x26'),
(352314, 1, 3523, 14, 0, 0, 'Cosmowrench', 'Cosmowrench is a small goblin outpost in the Vortex Fields at the far eastern edge of Netherstorm, close beneath Tempest Keep, a miniature Area 52 with its own bruisers, a weapon merchant and a flight master. Its most curious resident is a human named Sab''aoth, who once amused himself by accepting any challenge offered and now runs a reagent and poison business while writing a book about his time with the Twilight''s Hammer. One of his best sellers is the caustic blood of the warp chasers that swarm the Vortex Fields, which only his foul-mouthed imp, Zeppit, can gather safely.', 'warcraft.wiki.gg/wiki/Cosmowrench (Vortex Fields, easternmost edge, near Tempest Keep, miniature Area 52, Harpax, Kerpow, Sab''aoth a human); npc_text 10691 (Sab''aoth: challenges, reagent business, book about his experiences in Twilight''s Hammer); quest 10924 description and reward (warp chaser blood, Zeppit, nasty mouth); zone_areas 3724: Cosmowrench Bruiser, Harpax 20515, Sab''aoth 22479, Kerpow 22491; 3728: Warp Chaser x51, Zeppit 22484; creature_template 22479 subname Reagents & Poison Supplies; creature_template 20515 Harpax flight master, 22491 Kerpow Blastwrench weapon merchant'),
(352315, 1, 3523, 15, 0, 0, 'Tempest Keep', 'Beyond the Tempest Rift at Netherstorm''s eastern edge, the fortress of Tempest Keep hangs apart from the land. It is the seat of Prince Kael''thas Sunstrider and the reason the manaforges exist: their energy flows to it, and the Aldor reckon that once the last forge falls, the prince will be left to drain whatever reserves he has stored. Its satellites are the Mechanar, the Botanica, the Arcatraz and the Eye, and among their guardians is Commander Sarannis, holder of the key to the Violet Tower''s curse. From Shattrath City, the naaru A''dal sends champions to break into its satellites and to bring the prince to account.', 'warcraft.wiki.gg/wiki/Tempest_Keep (Kael''thas''s stronghold, satellites, Eye raid with Kael''thas); quest 10323 description (one manaforge keeps Tempest Keep functional, Kael will deplete stored energy); npc_text 9926 (energy sent to Tempest Keep); quest 10257 log text (Commander Sarannis in the Botanica); quest 10704 (A''dal: Arcatraz key), Trial of the Naaru chains (A''dal, Shattrath); zone_areas 3842: instance portals and The Arcatraz object'),
(352316, 1, 3523, 16, 0, 0, 'The Stormspire', 'The Stormspire is the seat of the Consortium in Netherstorm, a towering spire reached by an elevator from its base and flanked by the eco-domes Skyperch and Sutheron, where talbuks and lashers thrive under the ethereals'' shields. At its summit, Nexus-Prince Haramad receives visitors as a holographic image, a precaution against his many enemies. Below, dealers sell everything from exotic weapons to rare creatures, Head Engineer Ghabar tends the dome generators, a transmuter whose skill is known in a thousand worlds takes on alchemists, and a Cenarion Expedition envoy bargains for the domes'' secrets. Nexus-guards and alarm bots watch for trouble.', 'quest 10268 description (chamber atop the Stormspire, holographic image); npc_text 9993 (Haramad: many enemies, imaging device a precaution); quest 10423 description (elevator at the base of the spire); warcraft.wiki.gg/wiki/Netherstorm (Sutheron and Skyperch flank the Stormspire); quest 10424 description (main dome generator in Eco-Dome Sutheron); npc_text 10687 (Zarevhi: known in a thousand worlds); quest 10426 description (Aurine negotiating with the ethereals); zone_areas 3738: dealers 19533-19538, 20980, 20981, 20989, Ghabar 20811, Aurine Moonblaze 20871, Nexus-Guard, Alarm Bot; 3875/3876: Talbuk, Farahlon Lasher; creature_template 20811 Ghabar (Head Eco-Dome Engineer), 22427 Zarevhi (quest 10899 Master of Transmutation), 20871 Aurine Moonblaze (Cenarion Expedition)'),
(352317, 1, 3523, 17, 0, 0, 'Manaforge Ara', 'Manaforge Ara, on its own island in the northwest, is the last and best defended of the working forges, and it holds the secret the others only hinted at. Demons labor openly beside the Sunfury here: mo''arg warp-masters and gan''arg tinkers tend the machinery, a doomguard overmaster rules the Trelleum Mine beneath it, and its overseer bears the strangely un-elven name of Azarad. Not every elf is loyal. A demoted foreman in the mine calls the pilgrimage from Quel''Thalas a lie, and a magister has offered to defect. Across the bridge at Tuluman''s Landing, a Consortium agent poses as a weapon seller, and the young Aldor Kaylaan waits, sole survivor of the ten who went in.', 'quests 10323, 10365 descriptions (northwest, last manaforge, heavy opposition, Azarad an odd name for a sin''dorei); creature_template 20685 Overseer Azarad (type demon); quest 10432 description (servants of the Legion all over Ara); quest 10317 description (Trelleum Mine underneath Ara); quest 10318 description and reward (Sundown demoted, pilgrimage a lie, doomguard overmaster Grindgarr); quest 10202 description (Sunfury magister wishes to defect, stationed at Ara); quest 10275 description (Tuluman poses as a weapon merchant next to the bridge to Ara); npc_text 10209 (Kaylaan: ten of us went in, all others fell); zone_areas 3722: Mo''arg Warp-Master, Gan''arg Warp-Tinker, Overmaster Grindgarr; 3852: Tuluman, Kaylaan 20780'),
(352318, 1, 3523, 18, 0, 0, 'Forge Base: Oblivion and Gehenna', 'In the north of Netherstorm the Burning Legion has raised two forge bases. At Forge Base: Oblivion, gan''arg mekgineers assemble fel reavers, three of which stand aimed at the Stormspire waiting to be fueled, under Forgemaster Morug. Forge Base: Gehenna is the staging ground for the Legion''s army, where most of its teleporters stand, wrathbringers gather by the regiment, and mo''arg keep the gates in repair under the demon Silroth. Legion fel cannons guard both. Morug and Silroth each carry half of the stone that opens Socrethar''s teleporters, and close by lies Invasion Point: Overlord, the doorway to Socrethar''s own island.', 'quest 10855 description (three fel reavers aimed at the Stormspire, not yet active, gan''arg at Oblivion); quest 10856 description (Oblivion assembles fel reavers, Gehenna staging ground with teleporters, regiment of wrathbringers); quest 10857 description (mo''arg maintain the teleporters); quests 10407, 10508 (Morug and Silroth hold the stone halves); quest 10292 description (Legion cannon at the camps to the north); quests 10409, 10507 log text (Invasion Point: Overlord); zone_areas 3739/3740: Gan''arg Mekgineer, Inactive Fel Reaver, Legion Fel Cannon, Morug 20800, Wrathbringer, Silroth 20801'),
(352319, 1, 3523, 19, 0, 0, 'Socrethar''s Seat', 'Socrethar''s Seat is a craggy island off the northwestern corner of Netherstorm, from which the eredar Socrethar directs the Burning Legion''s campaign. No road reaches it. Only his most trusted lieutenants may pass, by a Legion teleporter that answers only to his stone, and wrath lords and hatecryers keep watch over the crags. It is here that champions of the Aldor and the Scryers come at last to face him, each backed by the power of a leader in Shattrath.', 'quest 10407 description (island in the northwest only his most trusted lieutenants can access, teleportation stone); quests 10409, 10507 log text (Legion teleporter in the northwestern corner, Voren''thal''s Presence); quest 10409 description (Orelis, Karja and Adyen sent); zone_areas 3742: Wrath Lord 20929, Hatecryer 20930, Socrethar 20132'),
(352320, 1, 3523, 20, 0, 0, 'Netherstone', 'The Netherstone is a crystal landmark in the north of Netherstorm that no one saw when this was a lush, green land; its formations were exposed only recently. They yield a mineral the Consortium calls farahlite, after the land''s old name, and the purest grade grows on the backs of the Farahlon giants who roam here under their patriarch, Cragskaar. Beyond it to the northeast lies Eco-Dome Farfield, a remote dome few ethereals visit, where scythetooth raptors nest and an ethereal technician tests repairs. That remoteness makes it a fine hiding place, and goblin poachers stash stolen dome generator pieces in the raptors'' nests.', 'quest 10290 description (landmark not seen when lush, newly exposed formations, farahlite named for the land''s former identity, giants); quest 10293 description (Cragskaar, patriarch of the Farahlon giants); quest 10430 description (Farfield beyond the Netherstone to the northeast, Tashar); quest 10435 description (generator pieces hidden in raptor nests, few ethereals); zone_areas 3850: Farahlon Breaker, Cragskaar 20202; 3874: Scythetooth Raptor, Dome Generator Segment, Tashar 20913'),
(352321, 1, 3523, 21, 0, 0, 'Ruins of Farahlon', 'High in the north of Netherstorm stand the Ruins of Farahlon, where old draenei banners still mark the stones, and which the Consortium''s Zephyrion means to excavate. The Burning Legion moved in first, a few weeks ago. Then one of its dreadlords, Culuthas, killed off all the other demons and summoned hounds and eyes of his own to serve him. What he guards is the ata''mal crystal, whose power he boasts will crush any challenger, and an image of Socrethar, the Legion''s master in Netherstorm, hovers close beside him.', 'quest 10335 description (three locations each near a draenei banner); quest 10336 description (Legion moved in weeks ago, Culuthas killed the other demons, summoned his own); creature_text 20138 (ata''mal crystal); quest 10276 description (crystal at the top of the Ruins of Farahlon, held by a demon); warcraft.wiki.gg/wiki/Socrethar (pressured Culuthas to bring the crystal back to the Legion); zone_areas 3741: Hound of Culuthas, Eye of Culuthas, Dead Doomguard, Culuthas 20138, Image of Socrethar 20133'),
(352322, 1, 3523, 22, 0, 0, 'The Protectorate Watch Post', 'On the island east of the Stormspire, the ethereal Protectorate keeps its Watch Post under Commander Ameer. Its soldiers fight on two fronts: against the void lord Dimensius at the ruined Manaforge Ultris, and against the Ethereum, whose Staging Grounds lie directly to the south. There, behind their perimeter defenses, the Ethereum train under Captain Zovax, keep fields of prisons holding creatures from all across the universe, and channel the void energy of the ruined manaforge to their own ends. At the post a researcher studies the pollution draining from Ultris, a flesh handler keeps subservient flesh beasts, and a nether drake waits to carry volunteers into battle.', 'quest 10969 description (Watch Post directly east of the Stormspire on the next island); npc_text 10058 (Ameer: void creature and Ethereum); quest 10339 description (Staging Grounds directly south, perimeter defenses, training facility, Captain Zovax); quest 10422 reward (fields of prisons, creatures from across the universe); quest 10385 reward (void energy at this manaforge); quest 10411 (Navuud, run-off of Dimensius); npc_text 10179 (flesh handlers); quest 10438 (Protectorate nether drake); zone_areas 3854/3878'),
(352323, 1, 3523, 23, 0, 0, 'Manaforge Ultris', 'Manaforge Ultris is the forge that failed. Pathaleon the Calculator calls what happened here a complete disaster: a tear in the nether now gapes atop the forge, and through it came Dimensius the All-Devouring, a void lord. The blood elves lost both the forge and the mine beneath it. Voidwraiths drift through the ruin, seeping sludge fills the surrounding pools, and in Access Shaft Zeon on its south side lie corpses drained by another void lord, Arconus, which hide flesh beasts waiting to burst out. The Ethereum patrol the Voidwind Plateau around it with nullifiers and jailors, while two Protectorate agents, split up in a firefight, hold out at the mine.', 'creature_text 21504 group 1 (Ultris was a complete disaster); quest 10437 description (tear in the nether atop Ultris that Dimensius came through); quest 10317 description (blood elves lost the mine underneath Ultris); quest 10411 description (seeping sludge in the pools around Ultris); quest 10270 description (Access Shaft Zeon on the south side of Ultris, Protectorate); quests 10345, 10353 and npc_text 10065 (Arconus, withered corpses, flesh beasts, Araxes and Ya-six); zone_areas 3736, 3880, 3735: Unstable Voidwraith, Seeping Sludge, Dimensius 19554, Withered Corpse, Fleshfiend, Ethereum Nullifier, Ethereum Jailor'),
(352324, 1, 3523, 24, 0, 0, 'Celestial Ridge', 'East of Manaforge Ultris, the Celestial Ridge is a forest of arcane crystals where nether dragons nest in every stage of growth, from eggs to full-grown dragons under a leader named Veraku. They hatch and mature quickly, drawing on the strange energies that forged their kind in the destruction of Draenor. Such creatures attract both profiteers and scholars. The ethereal Wind Trader Marid, who keeps a teleport pad on the ridge, wants their essence for a client among the blood elves, while two quiet watchers, the blue dragon Tyri and her companion Jorad Mace, hope to understand them before others rush to exploit them.', 'warcraft.wiki.gg/wiki/Netherstorm (Celestial Ridge, forest of arcane crystals, nether dragon nesting ground); quest 10271 description and reward (nether dragons in various stages of growth, a client K--, sell to the blood elves); quest 10274 description (hatch and mature rapidly, energies that forged their kind in the destruction of Draenor, Veraku); quest 10270 description (teleport pad); quest 10281 reward (Tyri and Jorad Mace); zone_areas 3737: Nether Drake, Nether Dragon, Nether Dragonkin Egg, Ethereal Teleport Pad, Tyri 20110, Jorad Mace 20111'),
(352325, 2, 3523, 1, 0, 0, 'Rocket-Chief Fuselage', 'Rocket-Chief Fuselage commands B.O.O.M. at Area 52 and drives the building of the X-52 Nether-Rocket, the craft on which he means to cruise through the Twisting Nether. He hires newcomers on the spot as Junior Technician 3rd Grade, promises promotion as fast as they bring him parts, and despairs aloud that his crew is at T-minus never. When a netherologist''s report warned that the storm would rip the region apart within months, his only complaint was that the timetable would have to move up. When the Burning Legion blamed Area 52 for its losses, he refused to let demons ruin his dream, and he once promoted the town''s rescuer straight to first officer.', 'npc_text 9844 (commander of B.O.O.M., T-minus NEVER); quest 10186 description (Junior Technician 3rd Grade); quest 10183 reward (move up the timetable); quest 10237 reward (Legion blaming us, dream of cruising through the Twisted Nether); quest 10249 reward (promotion to first officer)'),
(352326, 2, 3523, 2, 0, 0, 'Archmage Vargoth', 'Archmage Vargoth led the Kirin Tor contingent of the Alliance expedition, and when it became clear they were trapped in Outland he took his mages to the Plains of Farahlon and founded Kirin''Var Village. The Kirin Tor had entrusted him with two treasures of Krasus, a powerful sigil and the spellbook holding every spell Krasus mastered, both of them boons in the war against the orcs. When Kael''thas attacked, Vargoth gave his staff to his apprentice Ravandwyr and bade him flee, then was stripped of his possessions and sealed in the Violet Tower. He speaks to outsiders through an image the staff conjures, still wondering how fields that once looked like Westfall were ruined in mere months.', 'quest_template 10179 description (Vargoth''s own account of founding Kirin''Var); quest 10188 description (Sigil of Krasus, boon against the orcs, divested of possessions); quest 10192 description (Krasus''s Compendium, all the spells he mastered, advantage in the war); quest 10174 reward (gave Ravandwyr the staff and told him to flee); npc_text 9901 (image: fields like Westfall mere months ago); warcraft.wiki.gg/wiki/Kirin''Var_Village'),
(352327, 2, 3523, 3, 0, 0, 'Custodian Dieworth', 'Custodian Dieworth administered Kirin''Var Village on Archmage Vargoth''s behalf, and he still does, though he died in the attack with nearly everyone else. Unlike most of the village dead, he kept his memory and identity. He mourns colleagues whose spirits wander in mindless anger, tries to free a few by returning their treasured belongings to their homes, and has never forgotten the crimson-armored archer who led the assault. Bitter toward a prince who once called himself a member of the Kirin Tor, he hungers for vengeance on the Sunfury, yet admits that even when the killing is done he does not know how to let go.', 'quest_template 10179 description (Vargoth left administration of the town to Dieworth); npc_text 9848 (a man who once called himself a member of the Kirin Tor murdered all of us); npc_text 9847 (Morran: only the custodian and I preserved our full identities); quests 10182, 10305, 10306, 10307 (belongings returned); quest 10184 description; quests 10222, 10223 (vengeance; he does not know how to let go)'),
(352328, 2, 3523, 4, 0, 0, 'Nexus-Prince Haramad', 'Nexus-Prince Haramad leads the Consortium, the ethereal trading cartel whose agents work all over Outland. He keeps his chamber atop the Stormspire but greets visitors only as a holographic image, explaining that he has many enemies who would like to see him dead. His people are everywhere, from dealers posing as weapon merchants to nether-stalkers hunting traitors, and his ambitions run to the legendary: he seeks a crystal of draenei legend said to bestow godlike power on its bearer. When an outsider braved the Legion to win it and simply handed it over, Haramad declared that such selflessness had given him much to think about.', 'npc_text 9993 (imaging device, many enemies); quest 10268 description (chamber atop the Stormspire); quest 10265 description (our leader, Nexus-Prince Haramad); quest 10275 description (Tuluman posing as a weapon merchant, another of the nexus-prince''s agents); quest 10269 description (crystal from draenei legend, god-like powers); quest 10276 reward (selflessness, much to think about); nagrand.json 351812 (Consortium at Aeris Landing)'),
(352329, 2, 3523, 5, 0, 0, 'Commander Ameer', 'Commander Ameer leads the ethereal Protectorate in Netherstorm and addresses everyone else as fleshling. He tells the ethereals'' story plainly. The Ethereum were the ruling class of his homeworld, K''aresh, which his people fled shortly before the void lord Dimensius ravaged it; they vowed vengeance and have hunted him ever since, but vengeance has twisted them, and several nexus-princes broke away to found new factions, the Consortium among them. The Protectorate, he insists, was born as a reaction to the Ethereum, not to Dimensius, and he holds them just as dangerous. He works through transponders and projected images, and he broke the code of the Ethereum prisoner tags.', 'npc_text 10058, 10059, 10060, 10061 (Ameer''s gossip chain); quests 10339, 10384 (transponder, image); quests 10971, 10972, 10973 (prisoner tags decoded)'),
(352330, 2, 3523, 6, 0, 0, 'Tyri', 'Tyri, properly Tyrygosa of the brood of Malygos, is a blue dragon who came to the Celestial Ridge with her companion, Jorad Mace, to investigate rumors of a strange breed of dragons, perhaps even descendants of Deathwing. Watching through a projection, she warns newcomers that Wind Trader Marid is little better than a swindler. She fears that many will rush to exploit the nether dragons for profit without understanding what they are, and she hopes their powers might serve her own flight. Her plan is to cow them by defeating their leader, then keep them from falling under the sway of a malevolent power.', 'quest 10281 description and reward (projection, Marid a swindler, Tyrygosa of the brood of Malygos, Jorad Mace); quest 10272 description (rumors, descendants of Deathwing); quest 10274 description and reward (powers of use to my flight, displace Veraku, malevolent power); npc_text 9968'),
(352331, 2, 3523, 7, 0, 0, 'Socrethar', 'Socrethar is the eredar who leads the Burning Legion in Netherstorm, a name that is enough to make most draenei shudder. High Priestess Ishanah of the Aldor remembers him as he was, a renowned warrior of the Light whose only flaw was pride. From his island seat, reachable only by teleporters keyed to his own stone, he gives the Legion its orders, and the Aldor hold that his demons are the only reason Kael''thas could ever make use of the technology of Tempest Keep. He mocks those who come against him as a feeble army, and he is not above turning their own people against them.', 'quest 10407 description (infamous eredar, leads the Legion in Netherstorm, makes draenei shudder, island in the northwest); quest 10410 reward (Ishanah: once a renowned warrior of the Light, pride his only flaw); quest 10380 description (demons the only reason Kael''thas could use Tempest Keep technology); creature_text 20132 (mocks the Aldor army, Kaylaan)'),
(352332, 2, 3523, 8, 0, 0, 'Dimensius the All-Devouring', 'Dimensius the All-Devouring is a void lord who entered Netherstorm through a tear in the nether atop Manaforge Ultris. The tear binds him to the void and keeps him phased out of this world, beyond the reach of physical harm, while the void creatures he sends out ravage the island around him. He holds that time has meaning only to mortals and that in time all will be devoured. The ethereals have cause to hate him. By Commander Ameer''s account his void armies laid waste to their homeworld of K''aresh, and Professor Dabiri of the Protectorate, who plans to sever his conduit and send in Captain Saeed''s avengers, says they have hunted him for a thousand years.', 'quest 10437 description (tear atop Ultris, immune to physical harm, void creatures he sends out); creature_text 19554; npc_text 10059 (Dimensius unleashed his void armies on K''aresh); quests 10438, 10439 description and reward (Captain Saeed and the Avengers, hunted for a thousand years); warcraft.wiki.gg/wiki/Dimensius (Burning Crusade section only)'),
(352333, 3, 3523, 1, 0, 0, 'The X-52 Nether-Rocket', 'On the bridge into Netherstorm, Netherologist Coppernickels studies the ethereal currents and sends newcomers on to Area 52 with his overdue notes, which warn that the nether energies will rip the region apart within months. Rocket-Chief Fuselage simply moves up his timetable. Each new hire becomes a Junior Technician, sent to the Ruins of Enkaat for etherlithium crystals for the engine matrix, while a bot specialist sends a robot to salvage draenei machines. Chief Engineer Trep, who only took the post because the security jobs were gone, tries mana wraith essence and then solid elemental power to bring the engines to life. Boots the bartender brews rocket fuel from shale oil and nether ray venom, and the sappers zap their abandoned gear back from the Arklon Ruins, though one piece never arrives. Their old protege Sparky Uberthruster, who would not wear his helmet in the fissure, has become the infamous Dr. Boom and must be stopped.', 'quests 10183, 10260 (Coppernickels on the bridge, report); quests 10186, 10225, 10224, 10226 (crystals, Trep, essence, elemental power); npc_text 9916 (Trep applied for security); quests 10190, 10191 (Alley, Mark V); quests 10342, 10199 (Boots'' fuel); quest 10203 reward (four things sent, three arrived); quest 10221 description (Sparky Uberthruster became Dr. Boom, no helmet)'),
(352334, 3, 3523, 2, 0, 0, 'The Legion Comes for Area 52', 'Papa Wheeler of B.O.O.M. decides that the ethereals scavenging the Heap deserve to be robbed in turn, then sends help against the demons who have seized the Scrap Field. His wife, Mama Wheeler, who works among the ethereals at the Midrealm Post and is not pleased to hear herself called his partner, wants the small fel reaver parts the Legion leaves lying about, and then decides that killing the overseer Doomclaw might scare the demons away. It does the opposite. With Doomclaw dead, the Legion blames Area 52 and resolves to destroy it. Rocket-Chief Fuselage will not let demons ruin his dream and turns to Doctor Vomisa, Ph.T., whose Scrap Reaver X6000 combines fel reaver, ethereal and goblin technology. Its test run at the Proving Grounds becomes a real battle when the demons arrive, and the grateful rocket-chief promotes the pilot straight to first officer.', 'quests 10206, 10232, 10333, 10234, 10235, 10237, 10247, 10248, 10249 (descriptions and reward texts); creature_text 19832 (Vomisa: defend us with the Scrap Reaver)'),
(352335, 3, 3523, 3, 0, 0, 'The Curse of the Violet Tower', 'In Area 52 the Kirin Tor apprentice Ravandwyr seeks help for his master, Archmage Vargoth. Sent to flee with the archmage''s staff, he lost it to the demons of the Arklon Ruins, and once it is recovered he must replace its missing headpiece with a crystal taken from the ghosts of Enkaat. The staff can reach into the cursed Violet Tower, but only in hands outside the Kirin Tor. Through it the archmage''s image sets out what breaking the curse requires: the Sigil of Krasus from Spellbinder Maryana at Manaforge Coruu, Krasus''s Compendium from the houses of a rebel apprentice in Kirin''Var, the oculus that unlocks it from Sunfury Hold, and his familiar Glacius from Summoner Kanthin at Manaforge Duro. Then the golem Ar''kelos must fall. Even that is not enough. Scrying through a crystal from the giant Apex reveals that the key to the curse lies with Commander Sarannis, deep in Tempest Keep''s Botanica.', 'quests 10173, 10300, 10174, 10188, 10192, 10301, 10209, 10176, 10256, 10257 (descriptions, log texts and reward texts); creature_text 19938 (Image of Commander Sarannis)'),
(352336, 3, 3523, 4, 0, 0, 'The Ghosts of Kirin''Var', 'Custodian Dieworth and Lieutenant-Sorcerer Morran are the only spirits in Kirin''Var who still know themselves. Dieworth sets out to quiet the angry dead and to lay a few to rest by returning their treasures: a battle-mage''s sword, an heirloom storybook, a high elven cloak and a gnome''s beloved hat. Morran learns from a fragment that Kael''thas used a mana bomb, whose blast tore open the nether, and raises a ring of runes powered by energy taken from the blood elves to hold back the mana creatures. Yet the quieted spirits keep rising, and the village annals show that the mightiest mages are the most corrupted. A necromantic focus in the houses across the covered bridge exposes Naberius, the apprentice who betrayed the tower and has become a lich. Dieworth smashes his phylactery so that Naberius can be destroyed in the Chapel Yard, while vengeance falls on Sunfury Hold and on Master Daellis Dawnstrike at Manaforge Duro.', 'quests 10184, 10185, 10182, 10305, 10306, 10307 (Dieworth); quests 10343, 10239, 10240 (Morran, mana bomb, perimeter); quests 10312, 10316, 10314, 10319, 10320 (annals, focus, Naberius, phylactery, Chapel Yard); quests 10222, 10223 (Sunfury Hold, Daellis)'),
(352337, 3, 3523, 5, 0, 0, 'Shutting Down the Manaforges', 'A''dal sent the Aldor and the Scryers to Netherstorm to learn what Kael''thas is doing with his manaforges, and since they reached the Area 52 inn they have not stopped arguing. Spymaster Thalodien prefers assassinating Kael''s specialists, and the Aldor agree to raid Manaforge B''naar only so the Scryers will keep gathering information. Each side does its part. A captured roster names B''naar''s warp-masters and warp-engineers, and a magistrix finds that bloodgem crystals leave her people drunk on magic. A code scribbled on the roster hints at naaru technology, and a transcription of the forge''s console proves it. The pipelines carry warp energies strong enough to shatter Outland, so the forges cannot simply be smashed. Instead the naaru''s own safeguard is turned against them: access crystals taken from each overseer trigger emergency shutdowns at B''naar, Coruu, Duro and at last Ara, cutting Kael''thas off from his main source of power.', 'creature_text 19467 group 0 (A''dal sent us here to investigate Kael''s activities); npc_text 10022 (arguing since they arrived); quests 10189, 10193, 10204, 10329, 10330, 10338, 10365 (Scryer side); quests 10241, 10243, 10245, 10299, 10313, 10321, 10322, 10323 (Aldor side); quest 10321 reward (cut off from his main source of power)'),
(352338, 3, 3523, 6, 0, 0, 'A Pact with the Legion', 'How did Kael''thas master naaru technology so quickly? The Aldor follow captured briefings to Tuluman''s Landing, where the young Kaylaan is the only survivor of ten who went into Manaforge Ara. The Scryers hear the answer from a defecting magister and seize Legion orders bearing Kael''s seal. The prince has allied himself with the Burning Legion, and the eredar Socrethar commands it here. Both orders send word to Shattrath and take the halves of his teleportation stone from the forge bases. For the Aldor the price is bitter. Kaylaan, who cannot forgive the naaru for opening Shattrath to the Scryers he blames for his brother''s death, renounces the Aldor, and at Socrethar''s Seat the eredar sets him against Adyen the Lightwarden. High Priestess Ishanah offers herself for him, and his will at last breaks free of the Legion''s corruption, but he dies by Socrethar''s magic. The Scryers strike with Voren''thal''s power projected across Outland, and on that island Socrethar falls.', 'quests 10328, 10431, 10380, 10381, 10407, 10410, 10409 (Aldor side, descriptions and reward texts); quests 10202, 10432, 10508, 10509, 10507 (Scryer side); npc_text 10209 (Kaylaan); creature_text 20794 (Kaylaan the Lost: brother slain by Voren''thal, sworn enemies allowed into our city), 18537, 18538, 20132; quest 10323 reward (Burning Legion allied with Kael''thas)'),
(352339, 3, 3523, 7, 0, 0, 'The Ata''mal Crystal', 'The Aldor and the Scryers both send newcomers to aid the Consortium''s Nether-Stalker Khay''ji, hoping to win the ethereals over to the naaru. Khay''ji wants a crystal from the Arklon Ruins for Nexus-Prince Haramad, but the one taken from the dreadlord Pentatharon is not the prize, and the demons are plainly digging for something. Along the way he settles scores with the Zaxxis traitors at the Heap. The trail then runs to the Midrealm Post, where the blood elves have refused to pay for surveying equipment delivered to Manaforge Duro. Recovered, the equipment reaches Haramad at the Stormspire, and he reveals his aim: a crystal of draenei legend said to grant godlike power. Triangulation points near Manaforge Ultris and far to the west, reported to his agents Hazzin and Tuluman, place it atop the Ruins of Farahlon in the grip of the dreadlord Culuthas. It proves to be the ata''mal crystal, and Haramad sends it on to the naaru A''dal.', 'quests 10263, 10264 (Aldor and Scryer breadcrumbs); quests 10265, 10262, 10205, 10266, 10267, 10268, 10269, 10275, 10276 (descriptions and reward texts); creature_text 20138 (Culuthas: ata''mal crystal); quest 10280 description (Haramad gives the ata''mal crystal to be handed to A''dal; Shattrath''s quest, only mentioned)'),
(352340, 3, 3523, 8, 0, 0, 'The Ethereum', 'Commander Ameer suspects the Ethereum of preparing an assault on Ultris, so volunteers break through the perimeter of the Staging Grounds, topple Captain Zovax and report through a captured transponder. The Ethereum hide their plans well. Their data cells hold nothing, and only someone who drinks an Ethereum essence, at real risk to the mind, can see the relays that carry their secrets. The truth is worse than an attack: the Ethereum are not hunting Dimensius but becoming void, bonding themselves into nexus-stalkers through a manaforge energy tube. A holographic demolitionist overloads the conduit, and Nexus-King Salhadaar, who has waged his crusade for a thousand years, is brought down. Meanwhile missing Consortium dealers, a vanished captain and a rescued soldier lead the Protectorate to fields of prisons, and Ameer decodes the prisoners'' tags: a thousand worlds shattered, a thousand more to overcome. The trail leads to the stasis chambers of Bash''ir''s Landing in Blade''s Edge.', 'quests 10339, 10384, 10385, 10405, 10406, 10408 (descriptions and reward texts); creature_text 20454 (Salhadaar); quests 10969, 10970, 10971, 10972, 10973, 10422, 10425; quest 10974 (Bash''ir''s Landing, Blade''s Edge, only mentioned)'),
(352341, 3, 3523, 9, 0, 0, 'The Eco-Dome Thieves', 'The Consortium brings its eco-domes wherever it goes, but in Netherstorm the generators are failing. At Eco-Dome Midrealm the technician Mehrdad finds generator pieces at the bottom of a lake where crocolisks have taken an interest in them, and at the Stormspire Head Engineer Ghabar gets the same troubling readings from the main generator in Eco-Dome Sutheron. A prototype repair kit tested by Tashar at distant Eco-Dome Farfield works, but Tashar sees the pattern: key pieces have been stolen. The thieves are goblins of Area 52. Shauly Pore, posing as a furrier at the Midrealm Post, recruits non-goblin help, and his associates Action Jaxon and Audi the Needle, posing as hunters at the Stormspire, hide the stolen parts in raptor nests at Farfield, hoping to sell the spares to the Cenarion Expedition. Its envoy, Aurine Moonblaze, is studying how the domes drive plants and beasts to grow fast and fierce, dreaming of regrowing the ruined lands. Ghabar, unsettled, considers locking down the Stormspire.', 'quests 10417, 10418, 10423, 10424, 10430, 10436, 10440 (descriptions and reward texts); quests 10433, 10434, 10435 (Shauly, Jaxon and Audi); quests 10426, 10427, 10429 (Aurine Moonblaze)');
